import ssl
import smtplib
import os
import sys


class MailSender(object):
    MAIL_HOST = 'mailrelay.int.nokia.com'
    PORT = 25
    FROM_ADDR = 'uexgate.support@nokia.com'
    TO_ADDR = ['robert.zurek@nokia.com', 'witold.irlik@nokia.com']
    TOPIC = '[UExGate CMD Failure]'
    MAILING_DIR = os.path.dirname(os.path.abspath(__file__))
    LOG_PATH = os.path.join(MAILING_DIR, 'mail.log')

    def __init__(self, cmd_string, test_path, test_filename, test_case, stacktrace):
        self.cmd_string = cmd_string
        self.test_path = test_path
        self.test_filename = test_filename
        self.test_case = test_case
        self.stacktrace = stacktrace

    def send_mail(self):
        try:
            context = ssl.create_default_context()
            context.set_ciphers("DEFAULT@SECLEVEL=1")
            server = smtplib.SMTP(self.MAIL_HOST, self.PORT)
            server.starttls()
            server.sendmail(self.FROM_ADDR, self.TO_ADDR, self.get_msg())
        except Exception:
            pass

    def get_msg(self):
        msg_template = """\
Welcome UExGate Support!


There is a failure in invoking following test:
{test_path}
{test_filename} --> {test_case}


Command:
{cmd_string}


Elixir Stack:
{stacktrace}
"""
        message_from_template = msg_template.format(
            cmd_string=self.cmd_string,
            stacktrace=self.stacktrace,
            test_path=self.test_path,
            test_filename=self.test_filename,
            test_case=self.test_case
        )

        message = "From: {}\r\nTo: {}\r\nSubject: {}\n\n{}".format(
            self.FROM_ADDR, ", ".join(self.TO_ADDR), self.TOPIC, message_from_template)
        return message


if __name__ == '__main__':
    MailSender(*sys.argv[1:]).send_mail()
